请对以下 case 进行三维加权评分。

=== case_id ===
Case-04-focus-006

=== 用户原始指令 (query.txt) ===
给我做个专注卡片嘛，背景图上叠字那种，点一下跳到应用里，要看到已完成

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我做个专注卡片嘛，背景图上叠字那种，点一下跳到应用里，要看到已完成",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "focus": {
      "title": {
        "type": "string",
        "description": "专注模式卡片标题",
        "sampleValue": "专注模式"
      },
      "statusText": {
        "type": "string",
        "description": "当前专注状态或完成状态展示文本",
        "sampleValue": "已完成"
      },
      "summary": {
        "type": "string",
        "description": "专注完成后的简短说明",
        "sampleValue": "今日专注"
      },
      "entryHint": {
        "type": "string",
        "description": "整卡可点击进入应用的短提示",
        "sampleValue": "轻点进入"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_focus.png",
      "description": "专注模式图标素材，可作为专注卡片的背景视觉锚点或状态识别图形。"
    }
  ]
}

